with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MD_IS_PROPOSER_YES_NO as ROLE_TYPE
        , cast(null as varchar) as ROLE_CATEGORY
        , 'BA_HCP_PROD_8428_GPG_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8428_gpg_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MD_IS_PROPOSER_YES_NO as ROLE_TYPE
        , cast(null as varchar) as ROLE_CATEGORY
        , 'BA_HCP_PROD_8432_ECP_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8432_ecp_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , MD_IS_PROPOSER_YES_NO as ROLE_TYPE
        , cast(null as varchar) as ROLE_CATEGORY
        , 'BA_HCP_PROD_8433_FHC_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8433_fhc_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PD_BAGIC_RM_E_CODE))) as HUB_PARTY_HK
        , PLC_TYPE_OF_ASSIGNOR_DCLR as ROLE_TYPE
        , PLC_BORROWER_TYPE as ROLE_CATEGORY
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(PD_BAGIC_RM_E_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PART_ID))) as HUB_PARTY_HK
        , SUPPLIER_TYPE as ROLE_TYPE
        , cast(null as varchar) as ROLE_CATEGORY
        , 'BJAZ_NEFT_PARTNER_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_neft_partner_dtls') }}
    where (nullif('PARTID:' || nullif(trim(PART_ID),''), 'PARTID:')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ROLE_TYPE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ROLE_TYPE end)) as ROLE_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ROLE_CATEGORY end) as ROLE_CATEGORY,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when ROLE_TYPE is not null or ROLE_CATEGORY is not null
                     then md5(upper(coalesce(cast(ROLE_TYPE as varchar), '') || '|' || coalesce(cast(ROLE_CATEGORY as varchar), '')))
                end as SAT_LNK_PARTY_ROLE_CORE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_LNK_PARTY_ROLE_CORE_HASHDIFF is not null
